<?php require_once __DIR__.'/../includes/bootstrap.php';require_role('Student');check_csrf();$s=db()->prepare('SELECT id FROM students WHERE user_id=?');$s->execute([actor_id()]);$sid=(int)$s->fetchColumn();if($_SERVER['REQUEST_METHOD']==='POST'){db()->prepare('INSERT INTO complaints(student_id,category,subject,description,priority,status) VALUES(?,?,?,?,?,"Submitted")')->execute([$sid,$_POST['category'],$_POST['subject'],$_POST['description'],$_POST['priority']]);$_SESSION['flash']=['success','Ticket created'];redirect('complaints.php');}page_top('Support Center');flash();?><div class="card p-4"><form method="post" class="row g-3"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><div class="col-md-4"><select name="category" class="form-select"><option>Academic</option><option>Infrastructure</option><option>Library</option><option>Fees</option><option>Technical</option></select></div><div class="col-md-3"><select name="priority" class="form-select"><option>Low</option><option selected>Medium</option><option>High</option><option>Urgent</option></select></div><div class="col-md-5"><input name="subject" class="form-control" placeholder="Subject" required></div><div class="col-12"><textarea name="description" class="form-control" rows="5" placeholder="Describe the issue" required></textarea></div><button class="btn btn-primary col-md-2">Submit Ticket</button></form></div><?php page_bottom(); ?>